void proactive_page_create(void)
{
  lv_obj_t *panel;
  const int left_margin = THEME_CONTENT_PAD;
  const int content_width = PANEL_WIDTH - NAV_WIDTH - THEME_CONTENT_PAD * 2;

  /* Page title */

  theme_create_page_title(g_ui.content, "主动智能", left_margin, 16);
